#include <vector>
#include <algorithm>

class Solution {
private:
    std::vector<long long> ans;
    std::vector<std::vector<int>> adj;

    std::vector<long long> dfs(int u, int p, const std::vector<int>& cost) {
        std::vector<long long> cur = {cost[u]};
        for (int v : adj[u]) {
            if (v == p) continue;
            auto sub = dfs(v, u, cost);
            cur.insert(cur.end(), sub.begin(), sub.end());
        }
        std::sort(cur.begin(), cur.end());
        if (cur.size() >= 3) {
            long long p1 = cur[cur.size() - 1] * cur[cur.size() - 2] * cur[cur.size() - 3];
            long long p2 = cur[0] * cur[1] * cur[cur.size() - 1];
            ans[u] = std::max(0LL, std::max(p1, p2));
        } else {
            ans[u] = 1;
        }
        if (cur.size() > 5) {
            cur = {cur[0], cur[1], cur[cur.size() - 3], cur[cur.size() - 2], cur[cur.size() - 1]};
        }
        return cur;
    }
public:
    std::vector<long long> placedCoins(std::vector<std::vector<int>>& edges, std::vector<int>& cost) {
        int n = cost.size();
        ans.assign(n, 0);
        adj.assign(n, {});
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        dfs(0, -1, cost);
        return ans;
    }
};

import java.util.*;

class Solution {
    private long[] ans;
    private List<List<Integer>> adj;

    private List<Long> dfs(int u, int p, int[] cost) {
        List<Long> cur = new ArrayList<>();
        cur.add((long) cost[u]);
        for (int v : adj.get(u)) {
            if (v == p) continue;
            cur.addAll(dfs(v, u, cost));
        }
        Collections.sort(cur);
        int sz = cur.size();
        if (sz >= 3) {
            long p1 = cur.get(sz - 1) * cur.get(sz - 2) * cur.get(sz - 3);
            long p2 = cur.get(0) * cur.get(1) * cur.get(sz - 1);
            ans[u] = Math.max(0, Math.max(p1, p2));
        } else {
            ans[u] = 1;
        }
        if (sz > 5) {
            List<Long> pruned = new ArrayList<>();
            pruned.add(cur.get(0));
            pruned.add(cur.get(1));
            pruned.add(cur.get(sz - 3));
            pruned.add(cur.get(sz - 2));
            pruned.add(cur.get(sz - 1));
            return pruned;
        }
        return cur;
    }

    public long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        ans = new long[n];
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        dfs(0, -1, cost);
        return ans;
    }
}

var placedCoins = function(edges, cost) {
    const n = cost.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const ans = new Array(n).fill(0);
    function dfs(u, p) {
        let cur = [BigInt(cost[u])];
        for (const v of adj[u]) {
            if (v !== p) {
                cur.push(...dfs(v, u));
            }
        }
        cur.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
        const sz = cur.length;
        if (sz >= 3) {
            const p1 = cur[sz - 1] * cur[sz - 2] * cur[sz - 3];
            const p2 = cur[0] * cur[1] * cur[sz - 1];
            let maxP = 0n;
            if (p1 > maxP) maxP = p1;
            if (p2 > maxP) maxP = p2;
            ans[u] = Number(maxP);
        } else {
            ans[u] = 1;
        }
        if (sz > 5) {
            cur = [cur[0], cur[1], cur[sz - 3], cur[sz - 2], cur[sz - 1]];
        }
        return cur;
    }
    dfs(0, -1);
    return ans;
};
